// Package jsonschema derives a JSON Schema (draft 2020-12) from a Go type by
// reflection. It covers the shapes this CLI's documents use and nothing more;
// the committed schemas under schemas/ are generated by it and a test keeps
// them in step with the types.
//
// Field rules:
//   - the json tag names the property; "-" skips it;
//   - a field is required unless its tag has omitempty or omitzero;
//   - embedded structs are flattened;
//   - `enum:"A,B"` restricts a string field;
//   - `doc:"..."` becomes the property's description.
//
// A type that implements Schemaer supplies its own schema.
package jsonschema

import (
	"encoding/json"
	"fmt"
	"net/netip"
	"reflect"
	"sort"
	"strings"
	"time"
)

// Schemaer is implemented by types whose JSON form reflection can't infer,
// such as a custom MarshalJSON.
type Schemaer interface {
	JSONSchema() map[string]any
}

const draft = "https://json-schema.org/draft/2020-12/schema"

// For returns the schema of v's type, with $schema, $id and title set.
func For(v any, id, title string) map[string]any {
	s := schemaOf(reflect.TypeOf(v), nil)
	s["$schema"] = draft
	s["$id"] = id
	if title != "" {
		s["title"] = title
	}
	return s
}

// Marshal renders a schema as indented JSON with a trailing newline; keys are
// sorted, so the output is stable.
func Marshal(s map[string]any) ([]byte, error) {
	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

var (
	schemaerType = reflect.TypeFor[Schemaer]()
	timeType     = reflect.TypeFor[time.Time]()
	prefixType   = reflect.TypeFor[netip.Prefix]()
	addrType     = reflect.TypeFor[netip.Addr]()
	rawType      = reflect.TypeFor[json.RawMessage]()
)

func schemaOf(t reflect.Type, seen []reflect.Type) map[string]any {
	for t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	if t.Implements(schemaerType) {
		return reflect.Zero(t).Interface().(Schemaer).JSONSchema()
	}
	if reflect.PointerTo(t).Implements(schemaerType) {
		return reflect.New(t).Interface().(Schemaer).JSONSchema()
	}
	switch t {
	case timeType:
		return map[string]any{"type": "string", "format": "date-time"}
	case prefixType, addrType:
		return map[string]any{"type": "string"}
	case rawType:
		return map[string]any{}
	}
	switch t.Kind() {
	case reflect.String:
		return map[string]any{"type": "string"}
	case reflect.Bool:
		return map[string]any{"type": "boolean"}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return map[string]any{"type": "integer"}
	case reflect.Float32, reflect.Float64:
		return map[string]any{"type": "number"}
	case reflect.Slice, reflect.Array:
		return map[string]any{"type": "array", "items": schemaOf(t.Elem(), seen)}
	case reflect.Map:
		if t.Key().Kind() != reflect.String {
			panic(fmt.Sprintf("jsonschema: map key %s is not a string", t.Key()))
		}
		return map[string]any{"type": "object", "additionalProperties": schemaOf(t.Elem(), seen)}
	case reflect.Interface:
		return map[string]any{}
	case reflect.Struct:
		for _, s := range seen {
			if s == t {
				panic(fmt.Sprintf("jsonschema: recursive type %s", t))
			}
		}
		return structSchema(t, append(seen, t))
	}
	panic(fmt.Sprintf("jsonschema: unsupported kind %s (%s)", t.Kind(), t))
}

func structSchema(t reflect.Type, seen []reflect.Type) map[string]any {
	props := map[string]any{}
	var required []string
	collectFields(t, seen, props, &required)
	sort.Strings(required)
	s := map[string]any{
		"type":                 "object",
		"properties":           props,
		"additionalProperties": false,
	}
	if len(required) > 0 {
		s["required"] = required
	}
	return s
}

func collectFields(t reflect.Type, seen []reflect.Type, props map[string]any, required *[]string) {
	for i := range t.NumField() {
		f := t.Field(i)
		tag := f.Tag.Get("json")
		if tag == "-" {
			continue
		}
		name, opts, _ := strings.Cut(tag, ",")
		if f.Anonymous && name == "" {
			ft := f.Type
			for ft.Kind() == reflect.Pointer {
				ft = ft.Elem()
			}
			if ft.Kind() == reflect.Struct {
				collectFields(ft, seen, props, required)
				continue
			}
		}
		if !f.IsExported() {
			continue
		}
		if name == "" {
			name = f.Name
		}
		ps := schemaOf(f.Type, seen)
		if enum := f.Tag.Get("enum"); enum != "" {
			ps["enum"] = strings.Split(enum, ",")
		}
		if doc := f.Tag.Get("doc"); doc != "" {
			ps["description"] = doc
		}
		props[name] = ps
		if !strings.Contains(opts, "omitempty") && !strings.Contains(opts, "omitzero") {
			*required = append(*required, name)
		}
	}
}
